export function getLocalizedGuide(
  slug: string,
  locale: string,
): LocalizedGuide | null {
  const base = getGuideBySlug(slug);
  if (!base) return null;
  if (locale === "fr" && FR[slug]) {
    return FR[slug];
  }
  return {
    title: base.title,
    description: base.description,
    content: base.content,
    readTime: base.readTime,
  };
}
